package theme

import (
	"encoding/json"
	"io/fs"
	"os"
	"path/filepath"
	"testing"
	"testing/fstest"
)

// The web UI and the official catalog carry copies of the built-in themes,
// generated by make gen; these tests fail when the copies drift.
func TestUISpecMatchesTheUI(t *testing.T) {
	want, err := UISpec().JSON()
	if err != nil {
		t.Fatal(err)
	}
	got, err := os.ReadFile(filepath.Join("..", "..", "ui", "src", "design", "themes.json"))
	if err != nil {
		t.Fatal(err)
	}
	if string(got) != string(want) {
		t.Error("ui/src/design/themes.json is out of date; run make gen")
	}
	var spec Spec
	if err := json.Unmarshal(got, &spec); err != nil || len(spec.Themes) != 3 || len(spec.LayerCSS) != 3 || len(spec.Protected) != 4 {
		t.Errorf("spec = %d themes, %v", len(spec.Themes), err)
	}
}

func TestCatalogThemesMatchTheBuiltins(t *testing.T) {
	for _, th := range Builtins() {
		want, err := th.YAML()
		if err != nil {
			t.Fatal(err)
		}
		path := filepath.Join("..", "..", "catalog", "themes", th.ID, ThemeFile)
		got, err := os.ReadFile(path)
		if err != nil {
			t.Fatal(err)
		}
		if string(got) != string(want) {
			t.Errorf("%s is out of date; run make gen", path)
		}
		if _, err := ReadPackage(catalogPackage(t, filepath.Dir(path))); err != nil {
			t.Errorf("%s isn't a valid package: %v", path, err)
		}
	}
}

// catalogPackage returns the theme's package in a catalog item's directory:
// every file but the item's recipe and icon, which belong to the catalog.
func catalogPackage(t *testing.T, dir string) fs.FS {
	t.Helper()
	pkg := fstest.MapFS{}
	err := fs.WalkDir(os.DirFS(dir), ".", func(p string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() || p == "recipe.yaml" || p == "icon.svg" {
			return err
		}
		data, err := os.ReadFile(filepath.Join(dir, filepath.FromSlash(p)))
		pkg[p] = &fstest.MapFile{Data: data, Mode: 0o644}
		return err
	})
	if err != nil {
		t.Fatal(err)
	}
	return pkg
}
